-- Seed: especialidades, niveles y banco de preguntas (generado por scripts/generate-seed.mjs)
-- Portado de src/data/quizData.ts (Manual Clínico Odontológico UNERG).

-- ── Especialidades ──
create table if not exists public.specialties (
  id uuid primary key default gen_random_uuid(),
  slug text unique not null,
  name text not null,
  order_index integer not null default 0,
  icon text not null default '🦷',
  description text,
  levels_count integer not null default 3
);

-- ── Niveles ──
create table if not exists public.levels (
  id uuid primary key default gen_random_uuid(),
  specialty_id uuid not null references public.specialties(id) on delete cascade,
  level_number integer not null,
  title text not null,
  description text,
  xp_reward integer not null default 100,
  unique (specialty_id, level_number)
);

-- ── Preguntas de quiz ──
create table if not exists public.questions (
  id uuid primary key default gen_random_uuid(),
  specialty_slug text not null,
  level integer not null,
  question text not null,
  options jsonb not null,
  correct_index integer not null,
  explanation text,
  created_at timestamptz not null default now()
);
create index if not exists idx_questions_specialty_level on public.questions (specialty_slug, level);

-- ── Columnas de perfil (settings, racha) ──
alter table public.profiles add column if not exists settings jsonb not null default '{}'::jsonb;
alter table public.profiles add column if not exists streak_count integer not null default 0;
alter table public.profiles add column if not exists last_active_at timestamptz;
alter table public.profiles add column if not exists avatar_color text;

-- ── RLS ──
-- Perfil: el usuario crea su propia fila (upsert en el flujo de registro).
drop policy if exists "Users can insert own profile" on public.profiles;
create policy "Users can insert own profile" on public.profiles for insert with check (auth.uid() = id);

alter table public.specialties enable row level security;
alter table public.levels enable row level security;
alter table public.questions enable row level security;
drop policy if exists "Specialties readable" on public.specialties;
create policy "Specialties readable" on public.specialties for select to authenticated using (true);
drop policy if exists "Levels readable" on public.levels;
create policy "Levels readable" on public.levels for select to authenticated using (true);
drop policy if exists "Questions readable" on public.questions;
create policy "Questions readable" on public.questions for select to authenticated using (true);

